378	  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only), cap 3500 G");
379	  it.todo("cursed sword (premium 165 G) → cap 2000 G, based on the unmodified insurance value");
380	
381	  // --- Claim: standard reimbursement ---------------------------------------
382	  it("regular sword (steel, enchantment 3), damage 500 G → payout 400 G", () => {
383	    const result = runScenario({
384	      customer: { yearsWithMHPCO: 0 },
385	      steps: [
386	        {
387	          op: "quote",
388	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
389	        },
390	        {
391	          op: "claim",
392	          policy: 0,
393	          incident: {
