395	            damages: [{ itemType: "sword", amount: 500 }],
396	          },
397	        },
398	      ],
399	    });
400	
401	    // Full reimbursement minus the 100 G deductible; no special clause.
402	    // Insurance sum 1000 → cap 2000, so 2000 − 400 = 1600 remains.
403	    expect(result).toEqual({
